import { createWorkspace } from "@tigrisdata/agent-kit";
import * as fs from "fs";

async function main() {
  const now = new Date();

  const response = await createWorkspace("long-running-eval-ws", {
    ttl: { days: 7 },
    credentials: { role: "ReadOnly" }
  });

  if (response.error) {
    console.error("Error creating workspace:", response.error);
    process.exit(1);
  }

  if (!response.workspace) {
    console.error("No workspace returned.");
    process.exit(1);
  }

  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const output = {
    bucket: response.workspace.bucket,
    expires_at: expiresAt.toISOString()
  };

  fs.writeFileSync("/home/user/ttl-workspace/workspace.json", JSON.stringify(output, null, 2));
  console.log("Workspace created successfully");
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

